SELECT COUNT(*) AS "count_result" FROM triples t0, triples t1, triples t2 WHERE t0.p = 'http://schema.org/jobTitle' AND t1.s = 'http://db.uwaterloo.ca/~galuc/wsdbm/City137' AND t1.p = 'http://www.geonames.org/ontology#parentCountry' AND struct_pack(kind := 0::UTINYINT, value := t2.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t2.p = 'http://schema.org/nationality' AND t2.o = t1.o